const rows = $input.all();
if (!rows.length) return [];

const parts = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Africa/Cairo',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).formatToParts(new Date());

const map = Object.fromEntries(parts.map(p => [p.type, p.value]));
const today = `${map.year}-${map.month}-${map.day}`;

const cleanDate = (v) => String(v ?? '').trim().slice(0, 10);

const candidates = rows
  .filter(i => cleanDate(i.json.Publish_Date) >= today)
  .sort((a,b) => {
    const ad = cleanDate(a.json.Publish_Date);
    const bd = cleanDate(b.json.Publish_Date);
    if (ad !== bd) return ad.localeCompare(bd);
    return Number(a.json.row_number || 0) - Number(b.json.row_number || 0);
  });

return candidates.length ? [candidates[0]] : [];

const src=$json;
const pillar=String(src.Content_Pillar||'').trim().toLowerCase();
const imageText=String(src.Image_Text||'').trim();
const post=String(src['Post Description']||'').trim();
const strategy=String(src.Strategy||'').trim().toLowerCase();
const hook=String(src.Hook_Type||'').trim().toLowerCase();
const all=[pillar,imageText,post,strategy,hook].join(' ').toLowerCase();

const has=(re)=>re.test(all);
const wordCount=(s)=>String(s||'').trim().split(/\s+/).filter(Boolean).length;
const shortHeadline=(candidate,fallback)=>{
  const c=String(candidate||'').trim().replace(/[.!؟،,:;]+$/g,'');
  const wc=wordCount(c);
  return (c.length<=34 && wc>=2 && wc<=6) ? c : fallback;
};

let intent='diagnostic';
if(has(/خطوات|قائمة|checklist|framework|نموذج|طريقة من|\b[3-7]\s*(خطوات|نقاط|أخطاء|أسئلة)/i)) intent='framework';
else if(has(/تعلمت|من واقع|موقف حصل|حصل مع|شفت|قابلت|خبرتي|تجربتي|رأيي/i)) intent='story';
else if(has(/ليه|لماذا|سبب|جذري|تشخيص|خلل|مشكلة|تكلفة|هدر|اختناق/i)) intent='diagnostic';
else if(has(/مش كل|لا ت|أكبر خطأ|غلط|العكس|الحقيقة/i)) intent='contrarian';

let topic='diagnostic';
if(/تجرب/.test(pillar)||has(/تجربة العميل|رحلة العميل/)) topic='customer_experience';
else if(/منافس|عميل/.test(pillar)||has(/المنافس|فهم العميل/)) topic='customer_insight';
else if(/عرض استشاري|استشار|تشخيص/.test(pillar)||has(/تشخيص|الخلل الحقيقي|سبب جذري|قبل الحل|المشكلة نفسها أم مجرد نتيجة/)) topic='diagnostic';
else if(/وقت|تشغيل|عمليات|توثيق/.test(pillar)||has(/تشغيل|حرائق|اختناق|إجراء|توثيق/)) topic='operations';
else if(/توسع|نمو|فرع/.test(pillar)||has(/توسع|فرع جديد/)) topic='expansion';
else if(/ربح|ربحية|مبيعات/.test(pillar)||has(/ربح|هامش|مكسب/)) topic='profitability';
else if(/سيولة|كاش|تحصيل/.test(pillar)||has(/سيولة|كاش|تحصيل/)) topic='cashflow';
else if(/تسعير|سعر/.test(pillar)||has(/تسعير|سعر|خصم/)) topic='pricing';
else if(/قرار/.test(pillar)||has(/قرار|عشوائ|مخاطرة/)) topic='decision';

const presets={
  customer_experience:{
    label:'تجربة العميل',
    mood:'clean human service moment',
    palette:'warm ivory, soft sand, pale blue-gray, restrained copper',
    headline:'أين تخسر العميل؟',
    subhead:'التجربة تُحسم في التفاصيل الصغيرة.',
    people:'two',
    scene:'One realistic small-business service counter. One customer and one staff member in natural side profile, with one plain unbranded product package resting on the counter between them. The moment should show ease or friction through body language and spacing only. No hand close-up.'
  },
  customer_insight:{
    label:'فهم العميل',
    mood:'observational customer behavior',
    palette:'light sand, pale teal, clean ivory, restrained copper',
    headline:'راقب العميل أولًا',
    subhead:'السلوك الحقيقي أهم من افتراضاتك.',
    people:'two',
    scene:'One realistic retail shelf with only plain unbranded products. One customer compares two items while one business owner observes quietly from the background. Natural candid side-angle composition, no direct posing.'
  },
  operations:{
    label:'تشغيل',
    mood:'clear physical bottleneck',
    palette:'off-white, soft sage, pale teal, restrained copper',
    headline:'بتدير ولا بتطفي؟',
    subhead:'المشكلة المتكررة تحتاج نظامًا لا مجهودًا.',
    people:'none',
    scene:'One clean small-workshop sorting line made from smooth solid-color plastic trays, plain metal rollers and unmarked wooden parts. A single narrow station creates a visible pile-up of identical objects while the downstream path is open and orderly. No cardboard cartons or printed packaging.'
  },
  expansion:{
    label:'قرار توسع',
    mood:'disciplined growth',
    palette:'clean ivory, soft sky blue, warm stone, restrained copper',
    headline:'جاهز للتوسع فعلًا؟',
    subhead:'النمو الجيد يبدأ من أساس يتحمل.',
    people:'none',
    scene:'One realistic business property scene showing one finished healthy operating unit in the foreground and two unfinished expansion units behind it with neatly staged materials. The contrast must communicate prepared growth versus premature expansion without any signs.'
  },
  profitability:{
    label:'ربحية',
    mood:'sales versus retained value',
    palette:'off-white, pale steel blue, warm copper, restrained navy',
    headline:'مش كل بيع مكسب',
    subhead:'المبيعات لا تكفي لو الهدر أسرع.',
    people:'none',
    scene:'One clean production table with a growing stack of finished unmarked wooden products on one side, while offcuts, rejected parts and wasted raw material accumulate on the other. Use smooth blank surfaces only; no packaging or cardboard.'
  },
  cashflow:{
    label:'سيولة',
    mood:'visible flow bottleneck',
    palette:'light cool gray, pale mint, soft teal, restrained copper',
    headline:'فين الكاش؟',
    subhead:'البيع لا يفيد لو السيولة متوقفة.',
    people:'none',
    scene:'One clean storeroom flow using identical solid-color plastic bins moving through three simple metal stations. One station is blocked by excess bins, creating a clear bottleneck before a nearly empty outgoing area. No cardboard, labels, money, coins or banknotes.'
  },
  pricing:{
    label:'تسعير',
    mood:'value versus cost balance',
    palette:'warm cream, pale slate, muted gold, deep navy accents',
    headline:'السعر مش رقم',
    subhead:'القيمة والتكلفة لازم يتقابلوا.',
    people:'none',
    scene:'One elegant real physical balance scale on a clean worktable. A finished unbranded product and quality materials sit on one side; raw materials, tools and packaging inputs sit on the other. No price tags or numbers.'
  },
  decision:{
    label:'قرار إداري',
    mood:'clear choice contrast',
    palette:'warm ivory, pale blue, restrained amber, deep navy accents',
    headline:'قبل ما تقرر',
    subhead:'القرار السريع ممكن يكلفك طويلًا.',
    people:'none',
    scene:'One realistic business room with two visible routes through the space. One route is obstructed by unmarked wooden parts, loose tools and rework clutter; the other route is clean, open and ready. Do not use forks, road signs, arrows, cardboard boxes or labels.'
  },
  diagnostic:{
    label:'تشخيص أعمال',
    mood:'root-cause clarity',
    palette:'ivory, pale warm gray, blue-gray, restrained copper',
    headline:'فين الخلل الحقيقي؟',
    subhead:'شوف السبب قبل ما تزود الحلول.',
    people:'none',
    scene:'A striking close editorial photograph of a transparent glass flow channel carrying identical matte wooden spheres. Most spheres move freely, but one larger dark sphere blocks a narrow point and causes a visible queue behind it. Clean studio-like business aesthetic, realistic materials, no people, no packaging, no paper, no labels. The single blockage is the obvious focal point.'
  }
};

const p=presets[topic]||presets.diagnostic;
let feedFormat='diagnostic_object_scene';
if(intent==='story') feedFormat='single_person_editorial';
if(intent==='framework') feedFormat='document_cover';

let peopleMode=p.people;
let scene=p.scene;
if(feedFormat==='single_person_editorial'){
  peopleMode='one';
  scene='One candid editorial photograph inside a real small business. One generic Middle Eastern business owner or consultant is shown in side profile or three-quarter view, medium shot, observing the operation rather than posing for camera. Keep hands mostly out of frame. Use real physical products and workstations only.';
}
if(feedFormat==='document_cover'){
  peopleMode='none';
  scene='One clean editorial still life representing the business topic with only two or three relevant physical objects on a simple work surface. Large areas of calm negative space. No people, no typography, no infographic elements.';
}

const title=shortHeadline(imageText,p.headline);

return [{json:{
  ...src,
  Feed_Intent:intent,
  Feed_Format:feedFormat,
  Visual_Type:topic,
  Visual_Label:p.label,
  Visual_Mood:p.mood,
  Palette_Direction:p.palette,
  Image_Title_Final:title,
  Visual_Subhead:p.subhead,
  People_Mode:peopleMode,
  Visual_Scene:scene,
  Strategy_Version:'FEED-V5.0'
}}];

const item=$input.first();
const candidates=[
  item.json?.result?.image,
  item.json?.image,
  item.json?.result?.response?.image,
  item.json?.data?.image
].filter(v=>typeof v==='string' && v.length>10000);

if(!candidates.length) throw new Error('FLUX.2 Klein returned no usable base64 image');

let b64=candidates[0];
if(b64.includes('base64,')) b64=b64.split('base64,').pop();
const buf=Buffer.from(b64,'base64');
if(buf.length<120000) throw new Error('Generated image failed structural QC: file too small');

let width=0,height=0,mimeType='image/jpeg';
if(buf.length>24 && buf[0]===0x89 && buf[1]===0x50 && buf[2]===0x4e && buf[3]===0x47){
  mimeType='image/png';
  width=buf.readUInt32BE(16);
  height=buf.readUInt32BE(20);
}else if(buf[0]===0xff && buf[1]===0xd8){
  let i=2;
  while(i<buf.length-9){
    if(buf[i]!==0xff){i++;continue;}
    const marker=buf[i+1];
    if([0xc0,0xc1,0xc2,0xc3,0xc5,0xc6,0xc7,0xc9,0xca,0xcb,0xcd,0xce,0xcf].includes(marker)){
      height=buf.readUInt16BE(i+5);
      width=buf.readUInt16BE(i+7);
      break;
    }
    const len=buf.readUInt16BE(i+2);
    if(!len||len<2) break;
    i+=2+len;
  }
}
if(!width||!height) throw new Error('Generated image failed structural QC: dimensions not detected');
const ratio=width/height;
if(ratio<0.72||ratio>0.90) throw new Error('Generated image failed structural QC: portrait ratio out of range '+ratio.toFixed(3));

const strategy=$('Build Premium Visual Prompt').first().json;
const ext=mimeType==='image/png'?'png':'jpg';
return [{
  json:{
    ...strategy,
    Image_Model:'@cf/black-forest-labs/flux-2-klein-4b',
    QC_Structural:'PASS',
    QC_Width:width,
    QC_Height:height,
    QC_Aspect_Ratio:Number(ratio.toFixed(3))
  },
  binary:{
    image:{
      data:b64,
      mimeType,
      fileName:'linkedin_base_'+String(strategy.row_number||'x')+'.'+ext,
      fileExtension:ext
    }
  }
}];

const strategy=$('Build Premium Visual Prompt').first().json;
const baseId=$('Upload Base Image to Drive').first().json.id;
const presentationId=$json.id;
const requests=[
  {replaceAllText:{containsText:{text:'{{IMAGE_TEXT}}',matchCase:true},replaceText:strategy.Image_Title_Final}},
  {replaceAllText:{containsText:{text:'{{SUBHEAD}}',matchCase:true},replaceText:strategy.Visual_Subhead}},
  {replaceAllShapesWithImage:{
    imageUrl:'https://drive.google.com/uc?export=download&id='+baseId,
    replaceMethod:'CENTER_CROP',
    containsText:{text:'{{BASE_IMAGE}}',matchCase:true},
    pageObjectIds:['p1']
  }}
];
return [{json:{presentationId,batchPayload:{requests}}}];
